import Foundation
import AppKit
import CoreGraphics

/// Глобальный монитор горячих клавиш в стиле "hold-to-talk".
///
/// Логика: пользователь зажимает комбинацию модификаторов (по умолчанию Cmd+Ctrl).
/// Как только ВСЕ требуемые модификаторы зажаты одновременно — onPress().
/// Как только хотя бы один из требуемых модификаторов отпущен — onRelease().
///
/// Реализовано через CGEventTap на flagsChanged. Требует разрешения Accessibility.
final class GlobalHotkeyMonitor {
    var onPress: () -> Void = {}
    var onRelease: () -> Void = {}

    private var settings: AppSettings
    private var eventTap: CFMachPort?
    private var runLoopSource: CFRunLoopSource?
    private var isActive = false   // комбинация сейчас "нажата"

    init(settings: AppSettings) {
        self.settings = settings
    }

    func updateSettings(_ s: AppSettings) {
        self.settings = s
    }

    // MARK: - Accessibility

    /// Проверка/запрос разрешения Accessibility (нужно для глобального перехвата клавиш).
    @discardableResult
    static func ensureAccessibilityPermission(prompt: Bool) -> Bool {
        let opts = [kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String: prompt] as CFDictionary
        return AXIsProcessTrustedWithOptions(opts)
    }

    // MARK: - Start/Stop

    func start() {
        guard eventTap == nil else { return }

        let mask = (1 << CGEventType.flagsChanged.rawValue)

        let callback: CGEventTapCallBack = { _, type, event, refcon in
            guard let refcon = refcon else { return Unmanaged.passUnretained(event) }
            let monitor = Unmanaged<GlobalHotkeyMonitor>.fromOpaque(refcon).takeUnretainedValue()
            monitor.handle(type: type, event: event)
            return Unmanaged.passUnretained(event)
        }

        let selfPtr = Unmanaged.passUnretained(self).toOpaque()

        guard let tap = CGEvent.tapCreate(
            tap: .cgSessionEventTap,
            place: .headInsertEventTap,
            options: .listenOnly,
            eventsOfInterest: CGEventMask(mask),
            callback: callback,
            userInfo: selfPtr
        ) else {
            NSLog("[Hotkey] Не удалось создать event tap. Нужно разрешение Accessibility.")
            return
        }

        self.eventTap = tap
        let source = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, tap, 0)
        self.runLoopSource = source
        CFRunLoopAddSource(CFRunLoopGetCurrent(), source, .commonModes)
        CGEvent.tapEnable(tap: tap, enable: true)
        NSLog("[Hotkey] Event tap запущен")
    }

    func stop() {
        if let tap = eventTap {
            CGEvent.tapEnable(tap: tap, enable: false)
        }
        if let source = runLoopSource {
            CFRunLoopRemoveSource(CFRunLoopGetCurrent(), source, .commonModes)
        }
        eventTap = nil
        runLoopSource = nil
        isActive = false
    }

    // MARK: - Handling

    private func handle(type: CGEventType, event: CGEvent) {
        // Если tap отключился системой (таймаут) — переподключаем.
        if type == .tapDisabledByTimeout || type == .tapDisabledByUserInput {
            if let tap = eventTap {
                CGEvent.tapEnable(tap: tap, enable: true)
            }
            return
        }

        let flags = event.flags
        let allPressed = comboSatisfied(flags)

        NSLog("[Hotkey] flagsChanged: cmd=\(flags.contains(.maskCommand)) ctrl=\(flags.contains(.maskControl)) opt=\(flags.contains(.maskAlternate)) shift=\(flags.contains(.maskShift)) -> combo=\(allPressed) active=\(isActive)")

        if allPressed && !isActive {
            isActive = true
            NSLog("[Hotkey] >>> onPress (запись СТАРТ)")
            DispatchQueue.main.async { [weak self] in self?.onPress() }
        } else if !allPressed && isActive {
            isActive = false
            NSLog("[Hotkey] <<< onRelease (запись СТОП)")
            DispatchQueue.main.async { [weak self] in self?.onRelease() }
        }
    }

    /// Все требуемые модификаторы зажаты одновременно?
    private func comboSatisfied(_ flags: CGEventFlags) -> Bool {
        // Нет ни одного требования — комбинация невозможна.
        let requires = [
            settings.hotkeyRequiresCommand,
            settings.hotkeyRequiresControl,
            settings.hotkeyRequiresOption,
            settings.hotkeyRequiresShift
        ]
        guard requires.contains(true) else { return false }

        if settings.hotkeyRequiresCommand && !flags.contains(.maskCommand) { return false }
        if settings.hotkeyRequiresControl && !flags.contains(.maskControl) { return false }
        if settings.hotkeyRequiresOption  && !flags.contains(.maskAlternate) { return false }
        if settings.hotkeyRequiresShift   && !flags.contains(.maskShift) { return false }
        return true
    }
}
